/**
 * timeline.ts — scene timing for ElNino2026 (30 fps). The length is whatever the fitted narration needs.
 *
 * Scene lengths and narration anchors come from src/timing/timing.json, generated by
 * scripts/voiceover/fit_voiceover.py from the recorded take. Re-run it after re-recording; every visual
 * beat follows because scenes use cue(scene, phrase) instead of hard-coded frames.
 */
import timing from './timing/timing.json';

export const FPS = 30;
export const TOTAL_FRAMES: number = timing.totalFrames;
/** Chapter cards play over the first words of their scene (1.3 s). */
export const CHAPTER_CARD_FRAMES = 40;
export const END_SCREEN_FRAMES: number = timing.endScreenFrames;

export const CHAPTERS: Record<number, { number: number; title: string; titleSize?: number }> = {
  2: { number: 1, title: 'THE NORMAL PACIFIC' },
  3: { number: 2, title: 'WHEN IT BREAKS' },
  4: { number: 3, title: 'WHY 2026 IS DIFFERENT', titleSize: 128 },
  5: { number: 4, title: 'SAME OCEAN, OPPOSITE DISASTERS', titleSize: 92 },
  6: { number: 5, title: 'ON YOUR PLATE' },
};

export interface SceneTiming {
  id: number;
  from: number;
  durationInFrames: number;
  /** Frame (relative to the scene) where this scene's narration starts / ends. */
  narrationFrom: number;
  narrationTo: number;
}

export const SCENES: SceneTiming[] = timing.scenes.map((s) => ({
  id: s.id,
  from: s.from,
  durationInFrames: s.durationInFrames,
  narrationFrom: s.narrationFrom,
  narrationTo: s.narrationTo,
}));

export const sceneById = (id: number): SceneTiming => {
  const s = SCENES.find((x) => x.id === id);
  if (!s) throw new Error(`Unknown scene ${id}`);
  return s;
};

const anchors = timing.anchors as Record<string, Record<string, { from: number; to: number }>>;

/** Frame (relative to the scene start) at which `phrase` begins in the narration. */
export const cue = (scene: number, phrase: string, offset = 0): number => {
  const a = anchors[String(scene)]?.[phrase];
  if (!a) throw new Error(`cue(): "${phrase}" is not an anchor of scene ${scene} — add it to src/timing/anchors.json and re-run fit_voiceover.py`);
  return a.from + offset;
};

/**
 * Keyframes for interpolate() that stay strictly increasing however the narration is paced: each point is
 * pushed to at least 1 frame after the previous one. Use whenever a range mixes cues with fixed offsets.
 */
export const ramp = (...pts: number[]): number[] =>
  pts.reduce<number[]>((out, p) => [...out, out.length ? Math.max(p, out[out.length - 1] + 1) : p], []);

/** Frame (relative to the scene start) at which `phrase` ends. */
export const cueEnd = (scene: number, phrase: string, offset = 0): number => {
  const a = anchors[String(scene)]?.[phrase];
  if (!a) throw new Error(`cueEnd(): "${phrase}" is not an anchor of scene ${scene}`);
  return a.to + offset;
};

// Guard against drift: scenes must tile 0…TOTAL_FRAMES with no gaps.
SCENES.reduce((expectedFrom, s) => {
  if (s.from !== expectedFrom) throw new Error(`Scene ${s.id} starts at ${s.from}, expected ${expectedFrom}`);
  return s.from + s.durationInFrames;
}, 0);
if (SCENES.length !== 8 || SCENES[7].from + SCENES[7].durationInFrames !== TOTAL_FRAMES) {
  throw new Error(`El Niño scenes do not add up to ${TOTAL_FRAMES} frames`);
}
